//! Linear element editor parity (ex-511).
//!
//! `tests/fixtures/linear-editor.json` is upstream's own
//! `LinearElementEditor` (`packages/element/src/linearElementEditor.ts`) at
//! the pinned commit, generated by `tools/goldens/linear-editor-fixtures.mjs`
//! on hand-written and seeded random lines and arrows (sharp, round,
//! rotated, polygon, elbow, labelled): the point handles
//! (`POINT_HANDLE_SIZE` 10, `getPointIndexUnderCursor`, `isPointHandle`),
//! the midpoints (`getEditorMidPoints`, the segment length rule
//! `isSegmentTooShort`, `getSegmentMidpointHitCoords`,
//! `getSegmentMidPointIndex`, `shouldAddMidpoint`, `addMidpoint`), point
//! edits (`deletePoints`, `addPoints`) and label moves
//! (`handleBoundTextDragging`), each compared number for number and, for
//! the edits, element by element.

use excali_core::constants::DRAGGING_THRESHOLD;
use excali_core::element::Element;
use excali_editor::linear_element_editor::{
    add_midpoint, add_points, delete_points, get_editor_mid_points, get_point_index_under_cursor,
    get_points_global_coordinates, get_segment_mid_point_index, get_segment_midpoint_hit_coords,
    handle_bound_text_dragging, is_point_handle, is_segment_too_short, should_add_midpoint,
    AddedMidpoint, SegmentMidpoint, POINT_HANDLE_SIZE,
};
use excali_editor::scene::{MutationEnv, Scene};
use serde_json::{json, Value};

const FIXTURE: &str = include_str!("fixtures/linear-editor.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("linear-editor.json parses")
}

fn element(value: &Value) -> Element {
    Element::from_map(value.as_object().expect("an element").clone())
        .expect("an element upstream built")
}

fn elements(value: &Value) -> Vec<Element> {
    value
        .as_array()
        .expect("elements")
        .iter()
        .map(element)
        .collect()
}

fn num(v: &Value) -> f64 {
    v.as_f64().unwrap_or_else(|| panic!("a number, got {v}"))
}

fn point(v: &Value) -> [f64; 2] {
    [num(&v[0]), num(&v[1])]
}

fn opt_point(v: &Value) -> Option<[f64; 2]> {
    (!v.is_null()).then(|| point(v))
}

fn point_json(p: Option<[f64; 2]>) -> Value {
    match p {
        Some([x, y]) => json!([x, y]),
        None => Value::Null,
    }
}

fn indices(v: &Value) -> Vec<usize> {
    v.as_array()
        .expect("indices")
        .iter()
        .map(|i| i.as_u64().expect("an index") as usize)
        .collect()
}

/// Two numbers as the same double (`-0` equal to `0`): a rotated element's
/// numbers go through `Math.sin` and `Math.cos`, which `excali_math::js`
/// computes as Node 26's V8 does (ADR-011).
fn same_number(a: f64, e: f64) -> bool {
    a == e
}

fn same_json(actual: &Value, expected: &Value, path: &str) -> Result<(), String> {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            let (a, e) = (a.as_f64().expect("f64"), e.as_f64().expect("f64"));
            if same_number(a, e) {
                Ok(())
            } else {
                Err(format!("{path}: {a} != {e} (expected)"))
            }
        }
        (Value::Array(a), Value::Array(e)) => {
            if a.len() != e.len() {
                return Err(format!(
                    "{path}: {} items != {} (expected)",
                    a.len(),
                    e.len()
                ));
            }
            for (i, (a, e)) in a.iter().zip(e).enumerate() {
                same_json(a, e, &format!("{path}[{i}]"))?;
            }
            Ok(())
        }
        (Value::Object(a), Value::Object(e)) => {
            for key in e.keys().chain(a.keys()) {
                if key == "versionNonce" || key == "updated" {
                    continue;
                }
                match (a.get(key), e.get(key)) {
                    (Some(av), Some(ev)) => same_json(av, ev, &format!("{path}.{key}"))?,
                    (None, Some(ev)) => {
                        return Err(format!("{path}.{key}: missing, expected {ev}"))
                    }
                    (Some(av), None) => return Err(format!("{path}.{key}: {av}, expected no key")),
                    (None, None) => unreachable!(),
                }
            }
            Ok(())
        }
        (a, e) if a == e => Ok(()),
        (a, e) => Err(format!("{path}: {a} != {e} (expected)")),
    }
}

fn check(actual: &Value, expected: &Value, context: &str) {
    same_json(actual, expected, context)
        .unwrap_or_else(|e| panic!("{e}\n  port:     {actual}\n  upstream: {expected}"));
}

struct Env;

impl MutationEnv for Env {
    fn random_integer(&mut self) -> f64 {
        0.0
    }
    fn now(&mut self) -> f64 {
        1.0
    }
}

fn cases() -> Vec<Value> {
    fixture()["cases"].as_array().expect("cases").clone()
}

fn target<'a>(scene: &'a Scene, case: &Value) -> &'a Element {
    scene
        .get(case["target"].as_str().expect("a target id"))
        .expect("the target")
}

#[test]
fn constants_match_upstream() {
    let f = fixture();
    assert_eq!(POINT_HANDLE_SIZE, num(&f["pointHandleSize"]));
    assert_eq!(DRAGGING_THRESHOLD, num(&f["draggingThreshold"]));
}

#[test]
fn point_handles_and_global_points() {
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        let scene = Scene::new(elements(&case["elements"]));
        let map = scene.elements_map();
        let el = target(&scene, &case);
        let got: Vec<Value> = get_points_global_coordinates(el, &map)
            .into_iter()
            .map(|p| point_json(Some(p)))
            .collect();
        check(&Value::Array(got), &case["pointsGlobal"], id);
        let handles: Vec<Value> = (0..case["pointHandles"].as_array().expect("handles").len())
            .map(|i| Value::Bool(is_point_handle(el, i as isize - 1)))
            .collect();
        assert_eq!(Value::Array(handles), case["pointHandles"], "{id}");
    }
}

#[test]
fn midpoints_and_the_segment_length_rule() {
    let mut views = 0;
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        let scene = Scene::new(elements(&case["elements"]));
        let map = scene.elements_map();
        let el = target(&scene, &case);
        let pts = el.kind.points().expect("points");
        for view in case["views"].as_array().expect("views") {
            views += 1;
            let zoom = num(&view["zoom"]);
            let editing = view["editing"] == true;
            let context = format!("{id} zoom {zoom} editing {editing}");
            let mids: Vec<Value> = get_editor_mid_points(el, &map, editing, zoom)
                .into_iter()
                .map(point_json)
                .collect();
            check(&Value::Array(mids), &view["midPoints"], &context);
            let short: Vec<Value> = (0..pts.len() - 1)
                .map(|i| Value::Bool(is_segment_too_short(el, pts[i], pts[i + 1], i, zoom, &map)))
                .collect();
            assert_eq!(Value::Array(short), view["tooShort"], "{context}");
        }
    }
    assert!(views >= 150, "{views} views");
}

#[test]
fn point_and_midpoint_hits() {
    let mut probes = 0;
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        let scene = Scene::new(elements(&case["elements"]));
        let map = scene.elements_map();
        let el = target(&scene, &case);
        for view in case["views"].as_array().expect("views") {
            let zoom = num(&view["zoom"]);
            let editing = view["editing"] == true;
            for probe in view["probes"].as_array().expect("probes") {
                probes += 1;
                let [x, y] = point(&probe["point"]);
                let context = format!("{id} zoom {zoom} editing {editing} probe {x},{y}");
                assert_eq!(
                    get_point_index_under_cursor(el, &map, zoom, x, y) as i64,
                    probe["pointIndex"].as_i64().expect("an index"),
                    "{context}"
                );
                let hit = get_segment_midpoint_hit_coords(
                    el,
                    opt_point(&probe["hovered"]),
                    [x, y],
                    zoom,
                    editing,
                    &map,
                );
                check(&point_json(hit), &probe["hit"], &context);
            }
            for mid in view["midPointIndex"].as_array().expect("midPointIndex") {
                assert_eq!(
                    get_segment_mid_point_index(el, editing, zoom, point(&mid["point"]), &map)
                        as i64,
                    mid["result"].as_i64().expect("an index"),
                    "{id} zoom {zoom} editing {editing} midpoint {}",
                    mid["point"]
                );
            }
        }
    }
    assert!(probes >= 4000, "{probes} probes");
}

#[test]
fn should_add_midpoint_matches() {
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        let scene = Scene::new(elements(&case["elements"]));
        let el = target(&scene, &case);
        for s in case["shouldAdd"].as_array().expect("shouldAdd") {
            let m = &s["segmentMidpoint"];
            let segment_midpoint = SegmentMidpoint {
                value: opt_point(&m["value"]),
                index: m["index"].as_u64().map(|i| i as usize),
                added: m["added"] == true,
            };
            assert_eq!(
                should_add_midpoint(
                    el,
                    &segment_midpoint,
                    opt_point(&s["origin"]),
                    point(&s["pointer"]),
                    s["editing"] == true,
                    num(&s["zoom"]),
                ),
                s["result"] == true,
                "{id} {s}"
            );
        }
    }
}

#[test]
fn point_edits_and_label_moves() {
    let mut counts = std::collections::BTreeMap::<String, usize>::new();
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        let target_id = case["target"].as_str().expect("target");
        for op in case["ops"].as_array().expect("ops") {
            let kind = op["op"].as_str().expect("op");
            *counts.entry(kind.to_owned()).or_default() += 1;
            let mut scene = Scene::new(elements(&case["elements"]));
            let context = format!("{id} {op}");
            match kind {
                "addMidpoint" => {
                    let AddedMidpoint {
                        last_clicked_point,
                        selected_points_indices,
                    } = add_midpoint(
                        &mut scene,
                        &mut Env,
                        target_id,
                        op["index"].as_u64().expect("index") as usize,
                        point(&op["pointer"]),
                        op["gridSize"].as_f64(),
                    )
                    .expect("added");
                    assert_eq!(
                        json!({
                            "lastClickedPoint": last_clicked_point,
                            "selectedPointsIndices": selected_points_indices,
                        }),
                        op["result"],
                        "{context}"
                    );
                }
                "deletePoints" => delete_points(
                    &mut scene,
                    &mut Env,
                    target_id,
                    &indices(&op["indices"]),
                    op["uncommitted"] == true,
                ),
                "addPoints" => {
                    let added: Vec<[f64; 2]> = op["points"]
                        .as_array()
                        .expect("points")
                        .iter()
                        .map(point)
                        .collect();
                    add_points(&mut scene, &mut Env, target_id, &added);
                }
                "dragLabel" => {
                    let offset = [num(&op["offset"]["x"]), num(&op["offset"]["y"])];
                    let dragged = handle_bound_text_dragging(
                        &mut scene,
                        &mut Env,
                        target_id,
                        point(&op["pointer"]),
                        offset,
                    );
                    assert_eq!(Value::Bool(dragged), op["result"], "{context}");
                }
                other => panic!("unknown op {other}"),
            }
            let after: Vec<Value> = scene
                .elements()
                .iter()
                .map(|e| Value::Object(e.to_map()))
                .collect();
            check(&Value::Array(after), &op["after"], &context);
        }
    }
    for (kind, least) in [
        ("addMidpoint", 50),
        ("deletePoints", 100),
        ("addPoints", 50),
        ("dragLabel", 30),
    ] {
        assert!(
            counts.get(kind).copied().unwrap_or(0) >= least,
            "{counts:?}"
        );
    }
}
